 t.source=t.ids.map(i=>`${i}: ${fMap.get(i).archivo}:${fMap.get(i)['línea']}`);
 t.downstream=tasks.filter(x=>x.deps.includes(t.id)).length;
 t.effortBonus=Math.min(3,24/((t.hours[0]+t.hours[1])/2));
 t.score=+(8*sev[t.severity]+4*t.prob+4*t.impact+2*Math.min(3,t.downstream)+2*t.effortBonus).toFixed(1);
 const fast=t.phase===0||(t.phase===1&&sev[t.severity]>=4)||t.id==='T-014';
