// DAG y orden topológico por dependencias reales.
const order=[],seen=new Set(),active=new Set();
function visit(t){if(active.has(t.id))throw Error('Ciclo: '+t.id);if(seen.has(t.id))return;active.add(t.id);for(const d of t.deps)visit(tMap.get(d));active.delete(t.id);seen.add(t.id);order.push(t);}
tasks.forEach(visit);
function critical(k){const finish={},paths={};for(const t of order){let pred=null;for(const d of t.deps)if(!pred||finish[d]>finish[pred])pred=d;finish[t.id]=(pred?finish[pred]:0)+t.hours[k];paths[t.id]=[...(pred?paths[pred]:[]),t.id];}const last=tasks.reduce((a,b)=>finish[a.id]>finish[b.id]?a:b);return {hours:finish[last.id],path:paths[last.id]};}
// Calendario conservador por perfil, 5 días/semana, 6 h efectivas/día por persona completa.
// QA y OPS a media dedicación: 3 h/día; BE tiene dos personas. Fases secuenciales.
function schedule(k){const finish={},slots={BE:[0,0],FE:[0],QA:[0],OPS:[0]},rows=[],ph=[];let gate=0;
 for(let p=0;p<5;p++){let pending=tasks.filter(t=>t.phase===p);const startPhase=gate;
 while(pending.length){const ready=pending.filter(t=>t.deps.every(d=>finish[d]!=null));if(!ready.length)throw Error('Ciclo/calendario');const candidates=ready.map(t=>{const arr=slots[t.owner],slot=arr.indexOf(Math.min(...arr));return{t,slot,start:Math.max(gate,arr[slot],...t.deps.map(d=>finish[d]))};}).sort((a,b)=>a.start-b.start||a.t.priority.localeCompare(b.t.priority)||b.t.score-a.t.score||a.t.id.localeCompare(b.t.id));
 const {t,slot,start}=candidates[0],end=start+t.hours[k]/(t.owner==='QA'||t.owner==='OPS'?3:6);finish[t.id]=end;slots[t.owner][slot]=end;rows.push({id:t.id,phase:p,owner:t.owner,slot,startDay:+start.toFixed(2),endDay:+end.toFixed(2)});pending=pending.filter(x=>x.id!==t.id);}
 gate=Math.max(...tasks.filter(t=>t.phase===p).map(t=>finish[t.id]));ph.push({phase:p,startDay:+startPhase.toFixed(2),endDay:+gate.toFixed(2),weeks:+((gate-startPhase)/5).toFixed(2)});}
 return {weeks:+(gate/5).toFixed(2),phases:ph,tasks:rows};}
