const byPriority=Object.fromEntries(['P0','P1','P2','P3'].map(p=>[p,tasks.filter(t=>t.priority===p).length]));
const byOwner=Object.entries(owners).map(([id,name])=>({id,name,hours:sum(tasks.filter(t=>t.owner===id)),weeklyCapacity:capacity[id]}));
